68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
75	     * carrying the new owner's id, customer code and registration date.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    /**
80	     * Maximum number of owners a single city may hold. A create whose city already contains this many
81	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
82	     */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /**
86	     * Maximum number of owners that may be registered in a single day. A create made once this many
87	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
88	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
89	     */
90	    private static final int MAX_OWNERS_PER_DAY = 100;
91	
92	    /**
93	     * The number of owners that must already carry a given day's {@code registrationDate} before a
94	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
95	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
96	     */
97	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper) {
111	        this.clinicService = clinicService;
112	        this.ownerMapper = ownerMapper;
113	        this.petMapper = petMapper;
114	        this.visitMapper = visitMapper;
115	    }
