117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        normalizeAddress(ownerFieldsDto);
146	        rejectBlankOwnerFields(ownerFieldsDto);
147	        rejectInvalidPostcode(ownerFieldsDto);
148	        normalizeTelephone(ownerFieldsDto);
149	        normalizeEmail(ownerFieldsDto);
150	        String householdId = householdIdFor(ownerFieldsDto);
151	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
153	        rejectHouseholdDuplicate(householdId, sharesHousehold);
154	        rejectCityAtCapacity(ownerFieldsDto.getCity());
155	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
156	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
157	        long registeredThatDay = countRegisteredOn(registrationDate);
158	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        owner.setRegistrationDate(registrationDate);
162	        owner.setHouseholdId(householdId);
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
165	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
166	        markPossibleDuplicate(owner, sharesHousehold);
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        currentOwner.setAddress(ownerFieldsDto.getAddress());
184	        currentOwner.setCity(ownerFieldsDto.getCity());
185	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
186	        currentOwner.setLastName(ownerFieldsDto.getLastName());
187	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
188	        normalizeEmail(ownerFieldsDto);
189	        currentOwner.setEmail(ownerFieldsDto.getEmail());
190	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
